mapper.select:
SELECT id, theme, logo IS NOT NULL AS has_logo, slide_pagination_position,
       deck_title_position, section_title_position, project_logo_position
FROM projects WHERE id = #{id}

UPDATE projects SET updated_at = CASE WHEN title = #{title} THEN updated_at
                    ELSE MAX(updated_at + 1, #{updatedAt}) END, title = #{title}
WHERE id = #{id}
RETURNING id, title, updated_at

mapper.update:
UPDATE projects SET slide_pagination_position = #{slidePaginationPosition},
       deck_title_position = #{deckTitlePosition}, section_title_position = #{sectionTitlePosition},
       project_logo_position = #{projectLogoPosition}, updated_at = MAX(updated_at + 1, #{updatedAt})
WHERE id = #{id} AND (
    slide_pagination_position IS NOT #{slidePaginationPosition}
    OR deck_title_position IS NOT #{deckTitlePosition}
    OR section_title_position IS NOT #{sectionTitlePosition}
    OR project_logo_position IS NOT #{projectLogoPosition}
)
